mapper.select:
SELECT s.*, COALESCE(u.nickname, u.username) AS handled_by_name
FROM ai_cleanse_suggestion s
LEFT JOIN sys_user u ON u.id = s.handled_by
WHERE s.task_id = #{q.taskId}

    AND s.kind IN
    #{k}

AND s.status = #{q.status}
AND s.field = #{q.field}
AND s.confidence >= #{q.minConfidence}

    AND (s.record_code LIKE CONCAT('%', #{q.keyword}, '%') OR s.record_name LIKE CONCAT('%', #{q.keyword}, '%'))

ORDER BY s.group_no, s.id
